INSERT INTO permissions(permission_key,description) VALUES ('inventory:read','Read inventory'),('inventory:adjust','Post adjustments'),('inventory-ledger:read','Read ledger') ON CONFLICT DO NOTHING;
CREATE TABLE inventory_movements(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),movement_type VARCHAR(32) NOT NULL,idempotency_key VARCHAR(128) NOT NULL,request_fingerprint CHAR(64) NOT NULL,reason_code VARCHAR(32) NOT NULL,note VARCHAR(500),actor_subject VARCHAR(255) NOT NULL,correlation_id VARCHAR(128),occurred_at TIMESTAMPTZ NOT NULL,recorded_at TIMESTAMPTZ NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,idempotency_key),CHECK(movement_type IN('OPENING_BALANCE','MANUAL_ADJUSTMENT')),CHECK(reason_code IN('INITIAL_LOAD','MANUAL_CORRECTION','FOUND','DAMAGE','OTHER')));
CREATE TABLE inventory_ledger_entries(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,movement_id UUID NOT NULL,sequence INTEGER NOT NULL,variant_id UUID NOT NULL,warehouse_id UUID NOT NULL,location_id UUID NOT NULL,quantity_delta NUMERIC(19,6) NOT NULL,unit_code VARCHAR(8) NOT NULL,occurred_at TIMESTAMPTZ NOT NULL,recorded_at TIMESTAMPTZ NOT NULL,UNIQUE(tenant_id,movement_id,sequence),FOREIGN KEY(tenant_id,movement_id)REFERENCES inventory_movements(tenant_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,variant_id)REFERENCES catalog_product_variants(tenant_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,warehouse_id,location_id)REFERENCES warehouse_locations(tenant_id,warehouse_id,id)ON DELETE RESTRICT,CHECK(quantity_delta<>0));
CREATE TABLE inventory_balances(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,variant_id UUID NOT NULL,warehouse_id UUID NOT NULL,location_id UUID NOT NULL,on_hand_quantity NUMERIC(19,6) NOT NULL,unit_code VARCHAR(8) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,variant_id,warehouse_id,location_id),FOREIGN KEY(tenant_id,variant_id)REFERENCES catalog_product_variants(tenant_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,warehouse_id,location_id)REFERENCES warehouse_locations(tenant_id,warehouse_id,id)ON DELETE RESTRICT,CHECK(on_hand_quantity>=0));
CREATE INDEX idx_inventory_movements_recorded ON inventory_movements(tenant_id,recorded_at DESC);CREATE INDEX idx_inventory_ledger_variant_time ON inventory_ledger_entries(tenant_id,variant_id,occurred_at DESC);CREATE INDEX idx_inventory_ledger_location_time ON inventory_ledger_entries(tenant_id,location_id,occurred_at DESC);CREATE INDEX idx_inventory_balances_variant ON inventory_balances(tenant_id,variant_id);CREATE INDEX idx_inventory_balances_warehouse_variant ON inventory_balances(tenant_id,warehouse_id,variant_id);CREATE INDEX idx_inventory_balances_location_variant ON inventory_balances(tenant_id,location_id,variant_id);
CREATE FUNCTION prevent_inventory_history_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'inventory history is immutable' USING ERRCODE='55000';END$$;CREATE TRIGGER inventory_movements_immutable BEFORE UPDATE OR DELETE ON inventory_movements FOR EACH ROW EXECUTE FUNCTION prevent_inventory_history_mutation();CREATE TRIGGER inventory_ledger_immutable BEFORE UPDATE OR DELETE ON inventory_ledger_entries FOR EACH ROW EXECUTE FUNCTION prevent_inventory_history_mutation();
INSERT INTO role_permissions(tenant_id,role_id,permission_key)SELECT r.tenant_id,r.id,p.permission_key FROM roles r CROSS JOIN permissions p WHERE r.system_role AND r.name='ORGANIZATION_ADMIN' AND p.permission_key LIKE 'inventory%' ON CONFLICT DO NOTHING;INSERT INTO role_permissions(tenant_id,role_id,permission_key)SELECT r.tenant_id,r.id,p.permission_key FROM roles r CROSS JOIN permissions p WHERE r.system_role AND r.name IN('READ_ONLY','AUDITOR') AND p.permission_key IN('inventory:read','inventory-ledger:read') ON CONFLICT DO NOTHING;
